package experiment

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"github.com/cespare/xxhash/v2"
)

// The vectors are generated by the Python implementation (ml/experiment/bucketing.py); both
// languages must produce the same hash and bucket for every case.
func TestBucketMatchesSharedVectors(t *testing.T) {
	raw, err := os.ReadFile("../../../testdata/bucket_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v struct {
		Buckets   int               `json:"buckets"`
		Salts     map[string]string `json:"salts"`
		Reference []struct {
			Input string `json:"input"`
			XXH64 string `json:"xxh64"`
		} `json:"reference"`
		Cases []struct {
			Salt   string `json:"salt"`
			Unit   string `json:"unit"`
			XXH64  string `json:"xxh64"`
			Bucket int    `json:"bucket"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if v.Buckets != Buckets {
		t.Fatalf("vectors use %d buckets, code %d", v.Buckets, Buckets)
	}
	for layer, salt := range v.Salts {
		if Salts[layer] != salt {
			t.Errorf("layer %s: salt %q in vectors, %q in code", layer, salt, Salts[layer])
		}
	}
	for _, r := range v.Reference {
		if got := fmt.Sprintf("%016x", xxhash.Sum64String(r.Input)); got != r.XXH64 {
			t.Errorf("xxh64(%q) = %s, want %s", r.Input, got, r.XXH64)
		}
	}
	if len(v.Cases) < 200 {
		t.Fatalf("only %d cases", len(v.Cases))
	}
	for _, c := range v.Cases {
		if got := fmt.Sprintf("%016x", xxhash.Sum64String(c.Salt+":"+c.Unit)); got != c.XXH64 {
			t.Errorf("hash(%q, %q) = %s, want %s", c.Salt, c.Unit, got, c.XXH64)
		}
		if got := Bucket(c.Salt, c.Unit); got != c.Bucket {
			t.Errorf("Bucket(%q, %q) = %d, want %d", c.Salt, c.Unit, got, c.Bucket)
		}
	}
}

func TestAssignSplitsTheRangeByShare(t *testing.T) {
	cfg, err := NewConfig([]Experiment{{
		ID: "e1", Layer: "recall", From: 0, To: 1000, ConfigVersion: 3,
		Variants: []Variant{{Name: "control", Share: 50}, {Name: "treatment", Share: 50}},
	}})
	if err != nil {
		t.Fatal(err)
	}
	if cfg.Version != 3 {
		t.Fatalf("version %d", cfg.Version)
	}
	counts := map[string]int{}
	for u := 0; u < 20000; u++ {
		unit := UserUnit(int64(u))
		a := cfg.Assign(unit)
		if len(a) != len(Layers) {
			t.Fatalf("assigned %d layers", len(a))
		}
		r := a["recall"]
		want := "control"
		if r.Bucket >= 500 {
			want = "treatment"
		}
		if r.ExpID != "e1" || r.Variant != want {
			t.Fatalf("unit %s bucket %d: got %+v, want %s", unit, r.Bucket, r, want)
		}
		if a["rank"].Variant != DefaultVariant || a["rank"].ExpID != "" {
			t.Fatalf("rank layer has no experiment, got %+v", a["rank"])
		}
		counts[r.Variant]++
	}
	// 20,000 units split ~50/50 (5 sigma is about +-350).
	if d := counts["control"] - counts["treatment"]; d > 700 || d < -700 {
		t.Fatalf("unbalanced split %v", counts)
	}
}

func TestAssignIsStableAndLayersAreIndependent(t *testing.T) {
	same := 0
	for u := 0; u < 1000; u++ {
		unit := UserUnit(int64(u))
		if Bucket(Salts["recall"], unit) != Bucket(Salts["recall"], unit) {
			t.Fatal("bucket is not deterministic")
		}
		if Bucket(Salts["recall"], unit) == Bucket(Salts["rank"], unit) {
			same++
		}
	}
	if same > 10 { // independent layers agree on ~1 in 1000
		t.Fatalf("recall and rank buckets agree for %d of 1000 units", same)
	}
}

func TestNewConfigRejectsBadExperiments(t *testing.T) {
	ok := []Variant{{Name: "a", Share: 100}}
	cases := map[string][]Experiment{
		"layer":   {{ID: "x", Layer: "nope", From: 0, To: 10, Variants: ok}},
		"range":   {{ID: "x", Layer: "rank", From: 10, To: 10, Variants: ok}},
		"shares":  {{ID: "x", Layer: "rank", From: 0, To: 10, Variants: []Variant{{Name: "a", Share: 60}}}},
		"overlap": {{ID: "x", Layer: "rank", From: 0, To: 10, Variants: ok}, {ID: "y", Layer: "rank", From: 5, To: 20, Variants: ok}},
	}
	for name, exps := range cases {
		if _, err := NewConfig(exps); err == nil {
			t.Errorf("%s: expected an error", name)
		}
	}
}
